ON DUPLICATE KEY UPDATE `cricos_provider_code` = VALUES(`cricos_provider_code`), `institution_name` = VALUES(`institution_name`), `course_name` = VALUES(`course_name`), `vet_national_code` = VALUES(`vet_national_code`), `course_level` = VALUES(`course_level`), `course_duration_per_week` = VALUES(`course_duration_per_week`), `offshore_tuition_fee` = COALESCE(VALUES(`offshore_tuition_fee`), `offshore_tuition_fee`), `cricos_non_tuition_fee` = VALUES(`cricos_non_tuition_fee`), `cricos_estimated_total_cost` = VALUES(`cricos_estimated_total_cost`), `onshore_tuition_fee` = COALESCE(VALUES(`onshore_tuition_fee`), `onshore_tuition_fee`), `enrolment_fee` = COALESCE(`enrolment_fee`, VALUES(`enrolment_fee`)), `materials_fee` = COALESCE(`materials_fee`, VALUES(`materials_fee`)), `course_description` = COALESCE(NULLIF(`course_description`, ''), VALUES(`course_description`)), `entry_requirements` = COALESCE(NULLIF(`entry_requirements`, ''), VALUES(`entry_requirements`)), `english_requirements` = COALESCE(NULLIF(`english_requirements`, ''), VALUES(`english_requirements`)), `intakes` = COALESCE(NULLIF(`intakes`, ''), VALUES(`intakes`)), `total_course_duration` = COALESCE(NULLIF(`total_course_duration`, ''), VALUES(`total_course_duration`)), `assessment_style` = COALESCE(`assessment_style`, VALUES(`assessment_style`)), `apply_form` = COALESCE(VALUES(`apply_form`), `apply_form`), `is_expired` = 0, `updated_at` = VALUES(`updated_at`);
 Within the degree structure, candidates receive training in research methods and areas of study pertinent to their field, and work with supervisors on the preparation of their composition portfolio and dissertation.</p> <h5>Course Structure</h5> <p>Credit points required: 72</p>', NULL, 'No', '10 - Creative Arts', '1001 - Performing Arts', '100101 - Music', NULL, NULL, NULL, 'Masters Degree (Research)', 'No', 'No', NULL, NULL, NULL, 'English', '2 years full-time (104 weeks), 4 years part-time (208 weeks)', 'Semester 1', 104, NULL, 100900.0, 777.79, 101677.79, NULL, NULL, 'assignment', '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Admission to candidature for the Master of Museum and Heritage Studies (1.5 years full time) requires:; a bachelors degree with a major in one of Anthropology, Archaeology, Art History, Classics and Ancient History, Cultural Geography, Cultural Studies, Education, English, Gender Studies, History, Indigenous Studies or another major with an equivalent skills and knowledge base; and a minimum credit (65%) average calculated over the whole degree, from the University of Sydney, or an equivalent qualification.; Admission to candidature for the Master of Museum &amp; Heritage Studies (1 year full time) requires:; completion of the requirements for the embedded Graduate Certificate or Graduate Diploma in Museum and Heritage Studies with a minimum credit (65%) average, or an equivalent qualification or; an Honours degree in a relevant discipline or; relevant professional work experience and a bachelors degree with a minimum credit (65%) average or an equivalent qualification</li></ul>', NULL, 'https://www.sydney.edu.au/courses/courses/pr/master-of-music-composition0.html', 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '019180B', 'Master of Music (Musicology)', '<h4>Course Information</h4> <p>The Master of Music (Musicology) at the Sydney Conservatorium of Music trains students to become independent scholars in musicology. Students conduct research in various fields, culminating in a thesis of 25,000 to 40,000 words, and can choose coursework to enhance their understanding. Master of Music (Musicology) is for students wanting to explore musicology through independent research. It suits aspiring scholars interested in music theory, popular music studies, or ethnomusicology, with a potential pathway to PhD study.</p>', NULL, 'No', '10 - Creative Arts', '1001 - Performing Arts', '100101 - Music', NULL, NULL, NULL, 'Masters Degree (Research)', 'No', 'No', NULL, NULL, NULL, 'English', '2 years full-time (104 weeks), 4 years part-time (208 weeks)', 'Semester 1', 104, NULL, 100900.0, 777.79, 101677.79, NULL, NULL, 'assignment', NULL, NULL, 'https://www.sydney.edu.au/courses/courses/pr/master-of-music-musicology0.html', 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '019181A', 'Master of Commerce', '<h4>Course Information</h4> <p>Develop a global, responsible and adaptable mindset and the skills and experience to succeed in the dynamic future of work with our Master of Commerce. Co designed with industry, the program&#x27;s eight future focused specialisations will allow you to follow your passions and graduate in demand. The Master of Commerce is designed for students with prior business or management qualifications seeking to build on their existing expertise.</p> <h5>Course Structure</h5> <p>Credit points 72</p>', NULL, 'No', '08 - Management and Commerce', '0899 - Other Management and Commerce', '089999 - Management and Commerce, n.e.c.', NULL, NULL, NULL, 'Masters Degree (Coursework)', 'No', 'No', NULL, NULL, NULL, 'English', '1.5 years full-time (78 weeks)', 'Semester 1', 78, NULL, 98800.0, 579.0, 99379.0, NULL, NULL, 'assignment', '<h4>Academic Entry Requirements (International Students)</h4><ul><li>To be considered for admission, an applicant is required to have:; an Australian bachelors degree in commerce, business or related discipline with a credit average (65 percent) or equivalent qualification or; an Australian bachelors degree or higher in commerce, business or related discipline (minimum 50 percent average) or equivalent qualification, and satisfactory performance in the GMAT (for guidance, the class average score is 630) or GMAT Focus Edition (for guidance, the class average score is 585) or; an Australian bachelors degree in any discipline with a credit average (65 percent) or equivalent qualification and a minimum of one year relevant work experience or; an Australian bachelors degree with honours or higher in any discipline with a credit average (65 percent) or equivalent qualification or; the University of Sydney Graduate Diploma or Graduate Certificate in Commerce with a credit average (65 percent).</li></ul>', NULL, 'https://www.sydney.edu.au/courses/courses/pc/master-of-commerce0.html', 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '019182M', 'Graduate Diploma in Commerce', '<h4>Course Information</h4> <p>Our Graduate Diploma in Commerce will equip you with a global, responsible and adaptable mindset to succeed in the fourth industrial revolution and beyond. Co designed with industry, the program has new entrepreneurial and analytical streams to prepare you for an agile career. The Graduate Diploma in Commerce is specifically designed for students who have an undergraduate degree in another discipline or for applicants with relevant qualifications and work experience.</p> <h5>Course Structure</h5> <p>Credit points 48</p>', NULL, 'No', '08 - Management and Commerce', '0899 - Other Management and Commerce', '089999 - Management and Commerce, n.e.c.', NULL, NULL, NULL, 'Graduate Diploma', 'No', 'No', NULL, NULL, NULL, 'English', '1 year full-time (52 weeks)', 'Semester 1', 52, NULL, 64800.0, 386.0, 65186.0, NULL, NULL, 'assignment', '<h4>Academic Entry Requirements (International Students)</h4><ul><li>To be considered for admission, an applicant is required to have:; an Australian bachelors degree or higher with a minimum 60 percent average or equivalent qualification or; the University of Sydney Graduate Certificate in Commerce with a credit average (65 percent).</li></ul>', NULL, 'https://www.sydney.edu.au/courses/courses/pc/graduate-diploma-in-commerce.html', 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '019183K', 'Bachelor of Computer Science and Technology', NULL, NULL, 'No', '02 - Information Technology', '0201 - Computer Science', '020100 - Computer Science, n.f.d.', NULL, NULL, NULL, 'Bachelor Degree', 'No', 'No', NULL, NULL, NULL, 'English', '156 weeks', 'February, August; Semester 1; Semester 1, Semester 2; Semester 2', 156, NULL, 200500.0, 1175.45, 201675.45, NULL, NULL, 'assignment', NULL, NULL, NULL, 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '019184J', 'Bachelor of Psychology', NULL, NULL, 'No', '09 - Society and Culture', '0907 - Behavioural Science', '090701 - Psychology', NULL, NULL, NULL, 'Bachelor Degree', 'No', 'No', NULL, NULL, NULL, 'English', '208 weeks', 'February, August; Semester 1; Semester 1, Semester 2; Semester 2', 208, NULL, 241400.0, 1521.58, 242921.58, NULL, NULL, 'assignment', NULL, NULL, NULL, 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '019835A', 'Master of Philosophy (Business)', '<h4>Course Information</h4> <p>The University of Sydney Business School has an outstanding reputation for the quality of its research. The Master of Philosophy takes at least one year to complete of full time study, during which candidates undertake approved research and write a thesis of up to 50,000 words. This course is for high achieving graduates with an honours or postgraduate degree seeking to conduct advanced research in business. The course offers deep subject expertise and valuable analytical and communication skills, ideal for those pursuing careers in academia, industry, or research.</p>', NULL, 'No', '08 - Management and Commerce', '0803 - Business and Management', '080399 - Business and Management, n.e.c.', NULL, NULL, NULL, 'Masters Degree (Research)', 'No', 'No', NULL, NULL, NULL, 'English', '1 year full-time (52 weeks), 2 years part-time (104 weeks)', 'Semester 1', 104, NULL, 125700.0, 777.79, 126477.79, NULL, NULL, 'assignment', NULL, NULL, 'https://www.sydney.edu.au/courses/courses/pr/master-of-philosophy-business0.html', 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '020152G', 'Master of Administrative Law and Policy', '<h4>Course Information</h4> <p>The Master of Administrative Law and Policy offers the opportunity for public administrators specialising as lawyers or policy analysts to learn together within the disciplines of law, government and social policy. This course is designed for those who work in the fields of law, economics, government, social work or another relevant discipline, who wish to upgrade their undergraduate qualification(s) for the purposes of career advancement or professional and academic interest.</p> <h5>Course Structure</h5> <p>Credit points 48</p>', NULL, 'No', '09 - Society and Culture', '0909 - Law', '090999 - Law, n.e.c.', NULL, NULL, NULL, 'Masters Degree (Coursework)', 'No', 'No', NULL, NULL, NULL, 'English', '1 year full-time (52 weeks), 2 years part-time (104 weeks)', 'Semester 1', 52, NULL, 64800.0, 386.0, 65186.0, NULL, NULL, 'assignment', '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Admission to the degree requires:; a bachelors degree with a minimum credit average from the University of Sydney, or an equivalent qualification or; a bachelors degree from the University of Sydney, or an equivalent qualification; and evidence of two years of relevant professional experience</li></ul>', NULL, 'https://www.sydney.edu.au/courses/courses/pc/master-of-administrative-law-and-policy.html', 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '020155D', 'Master of Teaching', '<h4>Course Information</h4> <p>Become an exceptional early childhood teacher   a knowledgeable education professional, critical thinker and ethical leader. With flexible study options, gain practical experience through 40 days of teaching practice, a 45 day internship, and a professional research project. For graduates seeking a career change, seeking to shape the next generation and make a difference for young children, families and communities. Our program ensures you gain the confidence, knowledge, and skills to excel as an early childhood teacher.</p> <h5>Course Structure</h5> <p>Credit points 96</p>', NULL, 'No', '07 - Education', '0701 - Teacher Education', '070199 - Teacher Education, n.e.c.', NULL, NULL, NULL, 'Masters Degree (Coursework)', 'No', 'Yes', '35.00', '17', '595', 'English', '2 years full-time (104 weeks)', 'Semester 1', 104, NULL, 116400.0, 777.79, 117177.79, NULL, NULL, 'assignment', '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Admission to this course requires:; a bachelors degree in a relevant discipline from the University of Sydney or equivalent qualification and; the completion of any additional qualifying courses prescribed by the Faculty.</li></ul> <h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS score: A minimum result of 7.5 overall</li><li><strong>TOEFL iBT:</strong> TOEFL - IBT score: A minimum result of 105 overall</li></ul>', '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS score: A minimum result of 7.5 overall</li><li><strong>TOEFL iBT:</strong> TOEFL - IBT score: A minimum result of 105 overall</li></ul>', 'https://www.sydney.edu.au/courses/courses/pc/master-of-teaching-early-childhood.html', 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '022306M', 'Bachelor of Applied Science (Exercise and Sport Science)', '<h4>Course Information</h4> <p>Our Bachelor of Applied Science (Exercise and Sport Science) develops the skills to integrate exercise and physical activity with disease prevention and the promotion of good health, rehabilitation, nutrition and sports performance. You will learn how to integrate exercise and physical activity with health, sports performance and disease prevention. Exercise scientists help people recover from injury, maximise the performance of elite athletes, promote healthy ageing and improve people&#x27;s health and wellbeing.</p> <h5>Course Structure</h5> <p>Credit points required: 144</p>', NULL, 'No', '06 - Health', '0699 - Other Health', '069903 - Human Movement', NULL, NULL, NULL, 'Bachelor Degree', 'No', 'Yes', NULL, '20', '170', 'English', '3 years full-time (156 weeks)', 'Semester 1', 156, NULL, 218100.0, 1482.45, 219582.45, NULL, NULL, 'assignment', NULL, NULL, 'https://www.sydney.edu.au/courses/courses/uc/bachelor-of-applied-science-exercise-and-sport-science0.html', 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '022310D', 'University of Sydney Foundation Program - Standard Course', '<h4>Course Information</h4> <p>This program is available in intensive or standard formats. This means you can complete your course in as little as 40 weeks or up to 52 weeks, depending on your ability.</p>', NULL, 'No', '12 - Mixed Field Programmes', '1201 - General Education Programmes', '120199 - General Education Programmes, n.e.c.', NULL, NULL, NULL, 'Non AQF Award', 'Yes', 'No', '0.00', '0', '0', 'English', '52 weeks full-time', 'February, August; Semester 1; Semester 1, Semester 2; Semester 2', 52, NULL, 49800.0, 590.0, 50390.0, NULL, NULL, 'assignment', NULL, NULL, 'https://www.sydney.edu.au/study/applying/how-to-apply/international-students/preparation-programs.html', 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '022312B', 'Master of Information Technology', NULL, NULL, 'No', '02 - Information Technology', '0201 - Computer Science', '020100 - Computer Science, n.f.d.', NULL, NULL, NULL, 'Masters Degree (Coursework)', 'No', 'No', NULL, NULL, NULL, 'English', '52 weeks', 'February, August; Semester 1; Semester 1, Semester 2; Semester 2', 52, NULL, 57900.0, 373.0, 58273.0, NULL, NULL, 'assignment', NULL, NULL, NULL, 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '022575A', 'Doctor of Education', NULL, NULL, 'No', '07 - Education', '0799 - Other Education', '079999 - Education, n.e.c.', NULL, NULL, NULL, 'Doctoral Degree', 'No', 'No', NULL, NULL, NULL, 'English', '208 weeks', 'February, August; Semester 1; Semester 1, Semester 2; Semester 2', 208, NULL, 182800.0, 1260.0, 184060.0, NULL, NULL, 'assignment', '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 7.0 overall minimum 6</li></ul>', '<h4>English Language Requirements (International Students)</h4><ul><li><strong>IELTS Academic:</strong> IELTS 7.0 overall minimum 6</li></ul>', NULL, 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '023334K', 'Master of Social Work', NULL, NULL, 'No', '09 - Society and Culture', '0905 - Human Welfare Studies and Services', '090501 - Social Work', NULL, NULL, NULL, 'Masters Degree (Coursework)', 'No', 'No', NULL, NULL, NULL, 'English', '52 weeks', 'February, August; Semester 1; Semester 1, Semester 2; Semester 2', 52, NULL, 54100.0, 373.0, 54473.0, NULL, NULL, 'assignment', NULL, NULL, NULL, 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '023937E', 'Graduate Certificate in International Studies', NULL, NULL, 'No', '08 - Management and Commerce', '0803 - Business and Management', '080311 - International Business', NULL, NULL, NULL, 'Graduate Certificate', 'No', 'No', NULL, NULL, NULL, 'English', '26 weeks', 'February, August; Semester 1; Semester 1, Semester 2; Semester 2', 26, NULL, 28400.0, 193.0, 28593.0, NULL, NULL, 'assignment', NULL, NULL, NULL, 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '023939C', 'Graduate Certificate in Commerce', '<h4>Course Information</h4> <p>Our Graduate Certificate in Commerce will equip you with a global, responsible and adaptable mindset to succeed in the fourth industrial revolution and beyond. Co designed with industry, the program has new entrepreneurial and analytical streams to prepare you for an agile career. The Graduate Certificate in Commerce is specifically designed for students who have an undergraduate degree in another discipline or for applicants with relevant qualifications and work experience.</p> <h5>Course Structure</h5> <p>Credit points 24</p>', NULL, 'No', '08 - Management and Commerce', '0800 - Management and Commerce', '080000 - Management and Commerce, n.f.d.', NULL, NULL, NULL, 'Graduate Certificate', 'No', 'No', NULL, NULL, NULL, 'English', '6 months full-time (26 weeks)', 'Semester 1', 26, NULL, 32400.0, 193.0, 32593.0, NULL, NULL, 'assignment', '<h4>Academic Entry Requirements (International Students)</h4><ul><li>To be eligible for admission, an applicant is required to have:; an Australian bachelors degree or higher (or equivalent qualification) or appropriate qualifications and professional work experience in a relevant field (typically three years).</li></ul>', NULL, 'https://www.sydney.edu.au/courses/courses/pc/graduate-certificate-in-commerce.html', 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '023941J', 'Graduate Certificate in Public Policy', '<h4>Course Information</h4> <p>Gain a critical and multidisciplinary perspective on the global, national and local levels of a rapidly changing policy environment, with growing public scrutiny, shrinking resources, and new trans boundary challenges through the Graduate Certificate in Public Policy. The degree is designed for those working or looking to work in government and the public sector, and for those working in non government or private sector bodies who seek a better understanding of the role of government in public policy making.</p> <h5>Course Structure</h5> <p>Credit points 24</p>', NULL, 'No', '09 - Society and Culture', '0901 - Political Science and Policy Studies', '090103 - Policy Studies', NULL, NULL, NULL, 'Graduate Certificate', 'No', 'No', NULL, NULL, NULL, 'English', '6 months full-time (26 weeks)', 'Semester 1', 26, NULL, 28400.0, 193.0, 28593.0, NULL, NULL, 'assignment', '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Admission requires a bachelors degree with a major in the social sciences from the University of Sydney, or an equivalent qualification.</li></ul>', NULL, 'https://www.sydney.edu.au/courses/courses/pc/graduate-certificate-in-public-policy.html', 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '024656F', 'Graduate Certificate in Transport Management', NULL, NULL, 'No', '08 - Management and Commerce', '0899 - Other Management and Commerce', '089901 - Purchasing, Warehousing and Distribution', NULL, NULL, NULL, 'Graduate Certificate', 'No', 'No', NULL, NULL, NULL, 'English', '26 weeks', 'February, August; Semester 1; Semester 1, Semester 2; Semester 2', 26, NULL, 30850.0, 186.5, 31036.5, NULL, NULL, 'assignment', NULL, NULL, NULL, 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '024659C', 'Graduate Diploma in Educational Studies', '<h4>Course Information</h4> <p>Choose units of study to suit your interests or specialise in your chosen field from our offerings in educational management and leadership, educational psychology, international education, special and inclusive education, sports coaching, and teaching English to speakers of other languages. This diploma is designed to develop and support the careers of trained teachers who are teaching professionals, educational administrators, researchers and policymakers</p> <h5>Course Structure</h5> <p>Credit points 36</p>', NULL, 'No', '07 - Education', '0701 - Teacher Education', '070111 - Teacher Education: Higher Education', NULL, NULL, NULL, 'Graduate Diploma', 'No', 'No', NULL, NULL, NULL, 'English', '1 year full-time (52 weeks)', 'Semester 1', 52, NULL, 42600.0, 337.74, 42937.74, NULL, NULL, 'assignment', '<h4>Academic Entry Requirements (International Students)</h4><ul><li>Admission to candidature requires:; a Bachelor of Education from the University of Sydney or equivalent qualification and either the completion of postgraduate studies, or professional experience equivalent to one year full time in a field considered by the Faculty to be appropriate to the program of study or; a bachelors degree and either the Graduate Diploma in Education or Bachelor of Teaching or Master of Teaching from the University of Sydney or equivalent qualification or; a bachelors degree from the University of Sydney, or equivalent qualification, and either the completion of postgraduate studies, or professional experience equivalent to two years full time, in a field considered by the School to be appropriate to the program of studies.</li></ul>', NULL, 'https://www.sydney.edu.au/courses/courses/pc/graduate-diploma-in-educational-studies.html', 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '025098A', 'Bachelor of Commerce (Liberal Studies)', NULL, NULL, 'No', '08 - Management and Commerce', '0803 - Business and Management', '080399 - Business and Management, n.e.c.', NULL, NULL, NULL, 'Bachelor Degree', 'No', 'No', NULL, NULL, NULL, 'English', '208 weeks', 'February, August; Semester 1; Semester 1, Semester 2; Semester 2', 208, NULL, 235500.0, 1525.91, 237025.91, NULL, NULL, 'assignment', NULL, NULL, NULL, 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35'),
(1, '00026A', 'The University of Sydney', '025100A', 'Bachelor of Engineering / Bachelor of Arts', NULL, NULL, 'Yes', '03 - Engineering and Related Technologies', '0399 - Other Engineering and Related Technologies', '039999 - Engineering and Related Technologies, n.e.c.', '09 - Society and Culture', '0999 - Other Society and Culture', '099999 - Society and Culture, n.e.c.', 'Bachelor Degree', 'No', 'Yes', '35.00', '12', '420', 'English', '260 weeks', 'February, August; Semester 1; Semester 1, Semester 2; Semester 2', 260, NULL, 321700.0, 1921.8, 323621.8, NULL, NULL, 'assignment', NULL, NULL, NULL, 0, 0, '2026-11-05 09:34:35', '2026-11-05 09:34:35')
